<script setup lang="ts">const props=defineProps<{type:'in'|'out'}>();const {data:products}=await useFetch('/api/admin/inventory/overview',{transform:(r:any)=>r.data});const form=reactive({productId:'',quantity:1,movementAt:new Date().toISOString().slice(0,16),reference:'',counterparty:'',note:''}),message=ref(''),error=ref(''),loading=ref(false);async function submit(){message.value='';error.value='';loading.value=true;try{await $fetch(`/api/admin/inventory/${props.type}`,{method:'POST',body:{...form,movementAt:new Date(form.movementAt).toISOString()}});message.value=props.type==='in'?'Stok masuk berhasil dicatat.':'Stok keluar berhasil dicatat.';form.quantity=1;form.reference='';form.note=''}catch(e:any){error.value=e.data?.statusMessage||'Pencatatan gagal.'}finally{loading.value=false}}</script><template><form class="panel movement" @submit.prevent="submit"><div><label class="label">Produk *</label><select v-model="form.productId" class="field" required><option value="" disabled>Pilih produk</option><option v-for="p in products" :key="p.id" :value="p.id">{{p.sku}} — {{p.name}} (stok {{p.stock}})</option></select></div><div class="form-grid"><div><label class="label">Jumlah *</label><input v-model.number="form.quantity" class="field" type="number" min="1" required></div><div><label class="label">Tanggal / waktu *</label><input v-model="form.movementAt" class="field" type="datetime-local" required></div><div><label class="label">Referensi</label><input v-model="form.reference" class="field" placeholder="Contoh: SJ-0021"></div><div><label class="label">{{type==='in'?'Supplier / sumber':'Tujuan / keterangan'}}</label><input v-model="form.counterparty" class="field"></div></div><div><label class="label">Catatan</label><textarea v-model="form.note" class="field" rows="3"/></div><p v-if="message" class="success">{{message}}</p><p v-if="error" class="error">{{error}}</p><button class="btn btn-primary" :disabled="loading">{{loading?'Menyimpan…':type==='in'?'Catat barang masuk':'Catat barang keluar'}}</button></form></template><style scoped>.movement{padding:1.5rem;display:grid;gap:1rem;max-width:850px}.success{color:var(--success)}</style>
